package sk.verejnydohlad;

import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import sk.verejnydohlad.Models.*;
import static org.junit.jupiter.api.Assertions.*;

class NewsroomTest {
    static Config config(String... overrides){var env=new HashMap<String,String>(Map.of("APP_STORAGE_CONNECTION_STRING","UseDevelopmentStorage=true","AUTO_PUBLISH_ENABLED","true","RESEARCH_FLOW_ENABLED","true","NEWSROOM_FLOW_ENABLED","true"));for(int i=0;i<overrides.length;i+=2)env.put(overrides[i],overrides[i+1]);return Config.from(env);}
    static class DeskAi implements Ai {
        final MockAi mock=new MockAi();int planning,writing,feedback,corrections,reviews,checks;boolean rejectFirst,failWriting,failCorrection,rejectCorrected,rejectFirstReview,sensitive;
        String disposition="REVISE";
        public String model(){return mock.model();}public String editorModel(){return mock.editorModel();}
        public Map<String,Analysis> analyze(List<Release> r){return mock.analyze(r);}
        public List<StoryPitch> commission(List<Release> docs,List<Article> history){planning++;var result=new ArrayList<StoryPitch>();int i=0;for(var r:docs.stream().limit(6).toList())result.add(new StoryPitch(r.id(),List.of(r.id()),"Čo tento dokument znamená pre verejnosť?",List.of("NEWS","ANALYSIS","EXPLAINER").get(i++%3),90,"Useful synthetic commission"));return result;}
        public Draft generate(List<Release> r){if(failWriting)throw new IllegalStateException("Interrupted synthetic writing");return mock.generate(r);}
        public Draft write(StoryPitch p,List<Release> r){writing++;return generate(r);}
        public ResearchPlan plan(Draft d,List<Release> r){return new ResearchPlan("Čo vysvetľuje zdroj?",List.of("rozpočet"),List.of("rrz-sk"));}
        public ResearchBrief research(Draft d,List<Release> r,List<String> gaps){return new ResearchBrief(false,sensitive,"Čo vysvetľuje zdroj?",List.of(new GenerationClaim(r.getFirst().body(),r.getFirst().id(),"body-0")),List.of("Synthetic single-source scope"),List.of());}
        public Draft rewrite(Draft d,List<Release> r,ResearchBrief b){return d;}
        public Verification verify(Draft d,List<Release> r){checks++;return new Verification(!(rejectFirst && checks==1),sensitive,rejectFirst && checks==1?List.of("Missing attribution in the synthetic draft."):List.of());}
        public EditorDecision review(Draft d,List<Release> r){reviews++;return rejectFirstReview && reviews==1 || rejectCorrected && d.title().contains("Opravená")?new EditorDecision(false,false,List.of("Missing attribution."),"The paragraph needs exact attribution."):mock.review(d,r);}
        public RevisionFeedback feedback(Draft d,List<Release> r,List<String> issues){feedback++;return new RevisionFeedback(disposition,disposition.equals("REVISE")?List.of("Presne pripísať tvrdenie jeho pôvodcovi."):List.of(),"Synthetic editor disposition");}
        public Draft correct(Draft d,List<Release> r,List<String> issues){corrections++;if(failCorrection)throw new IllegalStateException("Interrupted correction");var title="[SYNTHETIC] Opravená testovacia správa";var claims=new ArrayList<>(d.claims());claims.set(0,new Claim(title,claims.getFirst().sourceId(),claims.getFirst().evidence()));return new Draft(title,d.perex(),d.category(),d.markdown(),claims);}
    }
    static Newsroom desk(MemoryStore store,DeskAi ai,Config config,Clock clock,PublicationCheck check){return new Newsroom(store,ai,config,clock,ResearchLookup.archiveOnly(),(s,g,d)->new Newsroom.Discovery.Result(0,0,List.of()),check);}
    static Newsroom desk(MemoryStore s,DeskAi ai){return desk(s,ai,config(),Fixtures.CLOCK,PublicationCheck.offline());}
    static MemoryStore sources(int count){var store=new MemoryStore();for(int i=0;i<count;i++){var r=Fixtures.release("desk-"+i);store.collect(r);store.releaseStatus(r,"CONTEXT",null);}return store;}
    @Test void unusedArchivedContextCanProduceThreeArticlesWithoutNewFeedItems(){var s=sources(4);var ai=new DeskAi();var result=desk(s,ai).run(false,RunScope.scheduled(),false);assertEquals(3,result.published());assertEquals(0,result.collected());assertEquals(3,s.orders().size());assertTrue(result.errors().isEmpty());assertEquals(1,ai.planning);assertEquals(3,ai.writing);assertTrue(s.budget("2026-10-12").calls()<=40);}
    @Test void preparationBuildsPrivateApprovedReserveAndMorningUsesItWithoutAnotherConcept(){
        var s=sources(3);var ai=new DeskAi();var prepared=desk(s,ai).run(false,RunScope.scheduled(),true);
        assertEquals(0,prepared.published());assertEquals(3,prepared.drafts());assertTrue(s.publicArticles.isEmpty());assertTrue(s.editorial().stream().allMatch(a->a.status()==Status.REVIEWED));
        int writing=ai.writing;var next=Clock.offset(Fixtures.CLOCK,Duration.ofDays(1));var result=desk(s,ai,config(),next,PublicationCheck.offline()).run(false,RunScope.scheduled(),false);
        assertEquals(3,result.published());assertEquals(writing,ai.writing);assertEquals(0,s.budget("2026-10-13").articleIds().size());assertEquals(6,s.budget("2026-10-13").calls());
        assertTrue(s.editorial().stream().allMatch(a->a.editionDate().equals("2026-10-13")));
    }
    @Test void reserveTargetStopsPreparationAndDoesNotSpendOnAlreadyApprovedInventory(){var s=sources(5);var ai=new DeskAi();var d=desk(s,ai,config("READY_ARTICLE_TARGET","3"),Fixtures.CLOCK,PublicationCheck.offline());d.run(false,RunScope.scheduled(),true);assertEquals(3,s.editorial().size());var budget=s.budget("2026-10-12");d.run(false,RunScope.scheduled(),true);assertEquals(budget,s.budget("2026-10-12"));assertEquals(3,ai.writing);}
    @Test void expiredNewsCannotPublishAndShortfallHasAnExplicitOperationalReason(){var s=sources(1);var ai=new DeskAi();desk(s,ai).run(false,RunScope.scheduled(),true);var later=Clock.offset(Fixtures.CLOCK,Duration.ofDays(3));var result=desk(s,ai,config(),later,PublicationCheck.offline()).run(false,RunScope.scheduled(),false);assertEquals(0,result.published());assertTrue(s.publicArticles.isEmpty());assertTrue(s.operations.values().stream().anyMatch(v->v.contains("Expired reserve article")));}
    @Test void changedCurrentEvidenceDefersPublicationWithoutReplacingOriginals(){
        var s=sources(1);var ai=new DeskAi();desk(s,ai).run(false,RunScope.scheduled(),true);var original=s.releases.values().iterator().next();
        PublicationCheck changed=(rs,g,d)->rs.stream().map(r->new Release(r.id(),r.sourceId(),r.organization(),r.originalUrl(),r.publishedAt(),r.collectedAt(),"Zmenený pôvodný dokument", "Úplne odlišný obsah dokumentu bez citovaných pasáží. ".repeat(4),Normalize.hash("changed"),r.blobPath())).toList();
        assertEquals(0,desk(s,ai,config(),Fixtures.CLOCK,changed).run(false,RunScope.scheduled(),false).published());assertEquals(original,s.release(original.id()));assertTrue(s.publicArticles.isEmpty());assertNotNull(s.operational("reserve-hold|"+s.editorial().getFirst().id()));
    }
    @Test void unavailableCurrentOriginalAndExhaustedCallsNeverPublishFromOldApproval(){for(boolean unavailable:List.of(false,true)){var s=sources(1);var ai=new DeskAi();desk(s,ai).run(false,RunScope.scheduled(),true);var old=s.budget("2026-10-12");if(!unavailable)s.budgets.put("2026-10-12",new Budget(40,old.articleIds()));PublicationCheck check=unavailable?(rs,g,d)->{throw new IllegalStateException("Unavailable");}:PublicationCheck.offline();assertEquals(0,desk(s,ai,config(),Fixtures.CLOCK,check).run(false,RunScope.scheduled(),false).published());assertTrue(s.publicArticles.isEmpty());}}
    @Test void lostPublishResponseResumesFreshApprovalWithoutAnotherPaidCall(){var s=sources(1);var ai=new DeskAi();s.failPublish=true;var d=desk(s,ai);assertEquals(0,d.run(false,RunScope.scheduled(),false).published());var budget=s.budget("2026-10-12");int reviews=ai.reviews;s.failPublish=false;assertEquals(1,d.run(false,RunScope.scheduled(),false).published());assertEquals(budget,s.budget("2026-10-12"));assertEquals(reviews,ai.reviews);}
    @Test void interruptedConceptResumesCommissionInsteadOfPlanningDuplicate(){var s=sources(1);var ai=new DeskAi();ai.failWriting=true;var d=desk(s,ai);assertEquals(0,d.run(false,RunScope.scheduled(),false).published());assertEquals(1,s.orders().size());ai.failWriting=false;assertEquals(1,d.run(false,RunScope.scheduled(),false).published());assertEquals(1,ai.planning);assertEquals(1,s.orders().size());}
    @Test void editorCanReturnExactlyOneCorrectedSuccessorWithFreshChecksAndImmutableRejection(){var s=sources(1);var ai=new DeskAi();ai.rejectFirst=true;var result=desk(s,ai).run(false,RunScope.scheduled(),false);assertEquals(1,result.published());assertEquals(1,ai.feedback);assertEquals(1,ai.corrections);assertEquals(1,s.editorial().stream().filter(a->a.status()==Status.REJECTED).count());assertEquals(2,s.orders().size());assertTrue(ai.checks>=3);assertTrue(ai.reviews>=2);}
    @Test void rejectedSuccessorCannotStartARevisionChain(){var s=sources(1);var ai=new DeskAi();ai.rejectFirst=true;ai.rejectCorrected=true;var d=desk(s,ai);assertEquals(0,d.run(false,RunScope.scheduled(),false).published());var budget=s.budget("2026-10-12");d.run(false,RunScope.scheduled(),false);assertEquals(1,ai.corrections);assertEquals(2,s.editorial().size());assertEquals(budget,s.budget("2026-10-12"));}
    @Test void finalEditorRejectionCanReturnToWriterAndNeverBecomesAnApprovalOfOriginal(){var s=sources(1);var ai=new DeskAi();ai.rejectFirstReview=true;assertEquals(1,desk(s,ai).run(false,RunScope.scheduled(),false).published());assertEquals(1,ai.feedback);assertEquals(1,ai.corrections);var rejected=s.editorial().stream().filter(a->a.status()==Status.REJECTED).findFirst().orElseThrow();assertEquals("AI editor: "+ai.editorModel(),rejected.reviewer());assertNull(rejected.approvedHash());assertEquals(1,s.publicArticles.size());}
    @Test void crashAfterSavingEditorInstructionsResumesWithoutBuyingFeedbackAgain(){var s=new MemoryStore(){boolean once=true;@Override public void operational(String key,String payload){super.operational(key,payload);if(once && key.startsWith("feedback|")){once=false;throw new IllegalStateException("Crash after feedback checkpoint");}}};s.collect(Fixtures.release("feedback-crash"));var ai=new DeskAi();ai.rejectFirst=true;var d=desk(s,ai);assertEquals(0,d.run(false,RunScope.scheduled(),false).published());assertEquals(1,ai.feedback);assertEquals(1,d.run(false,RunScope.scheduled(),false).published());assertEquals(1,ai.feedback);assertEquals(1,ai.corrections);}
    @Test void missingEvidenceIsHeldAndDoesNotGenerateRepeatedRewrites(){var s=sources(1);var ai=new DeskAi();ai.rejectFirst=true;ai.disposition="HOLD";var d=desk(s,ai);assertEquals(0,d.run(false,RunScope.scheduled(),false).published());d.run(false,RunScope.scheduled(),false);assertEquals(1,ai.feedback);assertEquals(0,ai.corrections);assertEquals(1,s.editorial().size());}
    @Test void sensitiveDraftNeverEntersFeedbackOrReserve(){var s=sources(1);var ai=new DeskAi();ai.sensitive=true;var result=desk(s,ai).run(false,RunScope.scheduled(),false);assertEquals(0,result.published());assertEquals(0,ai.feedback);assertEquals(0,ai.reviews);assertTrue(s.editorial().getFirst().sensitive());}
    @Test void manualDeskRetainsIndependentBudgetsAndSharedLease(){var s=sources(1);s.budgets.put("2026-10-12",new Budget(40,List.of("one","two","three","four","five","six")));var ai=new DeskAi();var scope=RunScope.adHoc();assertEquals(1,desk(s,ai).run(false,scope,false).published());assertEquals(40,s.budget("2026-10-12").calls());assertTrue(s.publicationScopes.values().contains(scope.label()));var budget=s.budget(scope.label());assertEquals(0,desk(s,ai).run(false,scope,false).published());assertEquals(budget,s.budget(scope.label()));try(var g=s.lock()){assertFalse(desk(s,ai).run(false,RunScope.adHoc(),false).errors().isEmpty());}}
    @Test void plannerCannotInventSourcesOrRepeatedPrimariesAndSelectionFavorsDifferentFormats(){var r=Fixtures.release("planning");var p=new StoryPitch(r.id(),List.of(r.id()),"Čo tento podklad znamená?","NEWS",90,"Relevant");assertThrows(IllegalArgumentException.class,()->Newsroom.validate(List.of(p,p),List.of(r)));assertThrows(IllegalArgumentException.class,()->Newsroom.validate(List.of(new StoryPitch("invented",List.of("invented"),p.question(),p.kind(),90,p.reason())),List.of(r)));var analysis=new StoryPitch("a",List.of("a"),p.question(),"ANALYSIS",70,p.reason());var news=new StoryPitch("b",List.of("b"),p.question(),"NEWS",80,p.reason());assertEquals(List.of(p,analysis,news),Newsroom.diverse(List.of(p,news,analysis)));}
}
